/* =========================
   VARIABLES GENERALES
========================= */
:root {
  --bg-main: #060913;
  --bg-secondary: #0d1327;
  --bg-card: rgba(255, 255, 255, 0.08);
  --bg-card-strong: rgba(255, 255, 255, 0.14);

  --text-main: #ffffff;
  --text-soft: #d6dcf8;
  --text-muted: #aeb8db;

  --accent-1: #8b2cff;
  --accent-2: #00e5ff;
  --accent-3: #ff2fa0;
  --accent-4: #ffd166;
  --accent-5: #7dff9b;

  --border-soft: rgba(255, 255, 255, 0.14);
  --shadow-main: 0 18px 45px rgba(0, 0, 0, 0.38);

  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 26px;

  --container-width: 1200px;
  --transition: 0.3s ease;
}

/* =========================
   RESETEO Y CONFIGURACIÓN BASE
========================= */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body,
h1,
h2,
h3,
p,
ul,
li {
  margin: 0;
}

body {
  font-family: "Rajdhani", sans-serif;
  background:
    radial-gradient(circle at top left, rgba(139, 44, 255, 0.24), transparent 24%),
    radial-gradient(circle at top right, rgba(0, 229, 255, 0.14), transparent 20%),
    linear-gradient(135deg, #050814 0%, #0a1022 45%, #101a37 100%);
  color: var(--text-main);
  line-height: 1.6;
}

img {
  display: block;
  width: 100%;
}

a,
button,
input,
textarea {
  transition: var(--transition);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--accent-4);
  outline-offset: 3px;
}

/* =========================
   ACCESIBILIDAD
========================= */
.skip-link {
  position: absolute;
  left: -9999px;
}

.skip-link:focus {
  left: 1rem;
  top: 1rem;
  z-index: 999;
  background: #ffffff;
  color: #000000;
  padding: 0.75rem 1rem;
  border-radius: 8px;
}

/* =========================
   CONTENEDOR GENERAL Y SECCIONES
========================= */
.container {
  width: min(92%, var(--container-width));
  margin: 0 auto;
}

.section-block {
  padding: 5rem 0;
}

.section-alt {
  background: rgba(255, 255, 255, 0.03);
}

.section-header {
  max-width: 780px;
  margin-bottom: 2.5rem;
}

.section-tag {
  display: inline-block;
  margin-bottom: 0.9rem;
  padding: 0.45rem 0.95rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--accent-4);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.section-header h2 {
  font-family: "Orbitron", sans-serif;
  font-size: clamp(2rem, 4vw, 2.8rem);
  line-height: 1.2;
  margin-bottom: 0.8rem;
}

.section-header p {
  color: var(--text-soft);
  font-size: 1.1rem;
}

/* =========================
   ENCABEZADO Y NAVEGACIÓN
========================= */
.site-header {
  position: sticky;
  top: 0;
  z-index: 200;
  background: rgba(4, 7, 20, 0.84);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border-soft);
}

.header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 0;
}

.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
  text-decoration: none;
  color: var(--text-main);
}

.logo-icon {
  display: inline-grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  font-size: 1.4rem;
  background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
  box-shadow: 0 0 25px rgba(139, 44, 255, 0.42);
}

.logo-text {
  font-family: "Orbitron", sans-serif;
  font-size: 1.7rem;
  font-weight: 900;
  letter-spacing: 0.02em;
}

.main-nav ul {
  padding: 0;
  list-style: none;
}

.nav-list {
  display: flex;
  align-items: center;
  gap: 1.4rem;
}

.nav-list a {
  text-decoration: none;
  color: var(--text-soft);
  font-size: 1.15rem;
  font-weight: 700;
}

.nav-list a:hover {
  color: var(--text-main);
}

/* =========================
   BOTONES
========================= */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 46px;
  padding: 0.9rem 1.4rem;
  border-radius: 999px;
  text-decoration: none;
  font-weight: 700;
  border: 1px solid transparent;
  cursor: pointer;
}

.btn-primary {
  color: #ffffff;
  background: linear-gradient(135deg, var(--accent-1), var(--accent-3));
  box-shadow: 0 12px 30px rgba(139, 44, 255, 0.35);
}

.btn-primary:hover {
  transform: translateY(-3px);
  filter: brightness(1.08);
}

.btn-secondary {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-soft);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.12);
}

/* =========================
   SECCIÓN HERO
========================= */
.hero-section {
  position: relative;
  min-height: 100vh;
  padding: 6rem 0 4rem;
  overflow: hidden;
  background:
    linear-gradient(
      90deg,
      rgba(4, 7, 20, 0.88) 0%,
      rgba(4, 7, 20, 0.55) 45%,
      rgba(4, 7, 20, 0.72) 100%
    ),
    url("data:image/png;base64,") center/cover no-repeat;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at left center, rgba(139, 44, 255, 0.22), transparent 35%),
    radial-gradient(circle at right center, rgba(0, 229, 255, 0.12), transparent 28%);
  pointer-events: none;
}

.hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.2fr 0.9fr;
  gap: 2rem;
  align-items: center;
}

.hero-label {
  display: inline-block;
  margin-bottom: 1rem;
  padding: 0.45rem 1rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: var(--accent-4);
  font-weight: 700;
}

.hero-text h1 {
  font-family: "Orbitron", sans-serif;
  font-size: clamp(2.6rem, 6vw, 5rem);
  line-height: 1.05;
  max-width: 760px;
  margin-bottom: 1rem;
  text-shadow: 0 0 18px rgba(0, 0, 0, 0.45);
}

.hero-description {
  max-width: 620px;
  color: var(--text-soft);
  font-size: 1.3rem;
  margin-bottom: 1.8rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 2rem;
}

/* =========================
   ESTADÍSTICAS DEL HERO
========================= */
.hero-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.stat-card {
  padding: 1.1rem;
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.09);
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-main);
  backdrop-filter: blur(8px);
}

.stat-card strong {
  display: block;
  font-family: "Orbitron", sans-serif;
  font-size: 1.4rem;
  margin-bottom: 0.2rem;
}

.stat-card span {
  color: var(--text-muted);
}

/* =========================
   PANEL DESTACADO
========================= */
.hero-panel {
  display: flex;
  justify-content: center;
}

.panel-card {
  width: 100%;
  max-width: 460px;
  padding: 2rem;
  border-radius: var(--radius-lg);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.13), rgba(255, 255, 255, 0.05)),
    linear-gradient(140deg, rgba(139, 44, 255, 0.26), rgba(0, 229, 255, 0.14));
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-main);
  backdrop-filter: blur(12px);
}

.panel-badge {
  display: inline-block;
  margin-bottom: 0.8rem;
  padding: 0.45rem 0.95rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: var(--text-main);
  font-weight: 700;
}

.panel-card h2 {
  font-family: "Orbitron", sans-serif;
  font-size: 2rem;
  margin-bottom: 0.8rem;
}

.panel-card p {
  color: var(--text-soft);
  font-size: 1.1rem;
  margin-bottom: 1rem;
}

.feature-list {
  list-style: none;
  padding: 0;
  margin-bottom: 1.4rem;
}

.feature-list li {
  padding: 0.65rem 0;
  color: var(--text-main);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

/* =========================
   SECCIÓN DE JUEGOS
========================= */
.games-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.game-card {
  overflow: hidden;
  border-radius: var(--radius-lg);
  background: var(--bg-card);
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-main);
  backdrop-filter: blur(8px);
}

.game-card:hover {
  transform: translateY(-8px);
}

.game-image {
  height: 250px;
  overflow: hidden;
}

.game-image img {
  height: 100%;
  object-fit: cover;
}

.game-card:hover .game-image img {
  transform: scale(1.06);
}

.game-info {
  padding: 1.4rem;
}

.game-tag {
  display: inline-block;
  margin-bottom: 0.8rem;
  padding: 0.35rem 0.8rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--accent-2);
  font-weight: 700;
}

.game-info h3 {
  font-family: "Orbitron", sans-serif;
  font-size: 1.35rem;
  margin-bottom: 0.6rem;
}

.game-info p {
  color: var(--text-soft);
  font-size: 1.08rem;
  margin-bottom: 1rem;
}

.card-link {
  text-decoration: none;
  color: var(--accent-4);
  font-weight: 700;
}

.card-link:hover {
  text-decoration: underline;
}

/* =========================
   SECCIÓN RETRO / CLÁSICOS
========================= */
.classic-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.4rem;
}

.classic-card {
  padding: 1.6rem;
  border-radius: var(--radius-md);
  background: var(--bg-card);
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-main);
}

.classic-card h3 {
  font-family: "Orbitron", sans-serif;
  margin-bottom: 0.7rem;
  font-size: 1.3rem;
}

.classic-card p {
  color: var(--text-soft);
  font-size: 1.05rem;
}

/* =========================
   SECCIÓN DE TORNEOS
========================= */
.tournaments-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.tournament-card {
  padding: 1.7rem;
  border-radius: var(--radius-lg);
  background: var(--bg-card);
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-main);
}

.tournament-card h3 {
  font-family: "Orbitron", sans-serif;
  margin-bottom: 1rem;
  font-size: 1.3rem;
}

.tournament-card p {
  color: var(--text-soft);
  font-size: 1.08rem;
  margin-bottom: 0.7rem;
}

/* =========================
   BANNER PROMOCIONAL
========================= */
.promo-section {
  padding-top: 0;
}

.promo-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  padding: 2rem;
  border-radius: var(--radius-lg);
  background:
    linear-gradient(135deg, rgba(139, 44, 255, 0.28), rgba(255, 47, 160, 0.18)),
    rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-main);
}

.promo-banner h2 {
  font-family: "Orbitron", sans-serif;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  margin-bottom: 0.7rem;
}

.promo-banner p {
  color: var(--text-soft);
  font-size: 1.08rem;
}

/* =========================
   SECCIÓN DE CONTACTO
========================= */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: start;
}

.contact-grid h2 {
  font-family: "Orbitron", sans-serif;
  font-size: clamp(2rem, 4vw, 2.6rem);
  margin-bottom: 0.8rem;
}

.contact-grid p {
  color: var(--text-soft);
  font-size: 1.1rem;
}

.contact-form {
  padding: 1.8rem;
  border-radius: var(--radius-lg);
  background: var(--bg-card);
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-main);
}

.form-group {
  margin-bottom: 1rem;
}

.form-group label {
  display: inline-block;
  margin-bottom: 0.45rem;
  font-weight: 700;
  font-size: 1.05rem;
}

.form-group input,
.form-group textarea {
  width: 100%;
  padding: 0.95rem 1rem;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-main);
  font-family: "Rajdhani", sans-serif;
  font-size: 1.05rem;
}

.form-group input::placeholder,
.form-group textarea::placeholder {
  color: #c8cee7;
}

/* =========================
   PIE DE PÁGINA
========================= */
.site-footer {
  background: rgba(0, 0, 0, 0.28);
  border-top: 1px solid var(--border-soft);
}

.footer-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 1.5rem 0;
}

.footer-content p {
  color: var(--text-muted);
}

.footer-links {
  display: flex;
  gap: 1rem;
  list-style: none;
  padding: 0;
}

.footer-links a {
  text-decoration: none;
  color: var(--text-soft);
}

.footer-links a:hover {
  color: var(--text-main);
}

/* =========================
   DISEÑO RESPONSIVE
========================= */
@media (max-width: 1024px) {
  .hero-grid,
  .games-grid,
  .classic-grid,
  .tournaments-grid,
  .contact-grid {
    grid-template-columns: 1fr 1fr;
  }

  .hero-stats {
    grid-template-columns: 1fr;
  }

  .header-content {
    flex-wrap: wrap;
  }

  .promo-banner {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 768px) {
  .main-nav {
    width: 100%;
  }

  .nav-list {
    flex-wrap: wrap;
    justify-content: center;
  }

  .hero-grid,
  .games-grid,
  .classic-grid,
  .tournaments-grid,
  .contact-grid {
    grid-template-columns: 1fr;
  }

  .hero-section {
    min-height: auto;
    padding-top: 5rem;
    background-position: center;
  }

  .hero-text h1 {
    font-size: 2.6rem;
  }

  .footer-content {
    flex-direction: column;
    align-items: flex-start;
  }
}